<?php
declare(strict_types=1);
use App\Services\AttendanceNotificationService;use App\Services\AttendancePushService;use App\Services\IntegrationDispatcherService;use App\Services\WebhookService;
require_once __DIR__.'/../app/helpers/bootstrap.php';if(PHP_SAPI!=='cli'){http_response_code(404);exit(1);}$task=(string)($argv[1]??'');$tasks=['integration'=>static fn()=>(new IntegrationDispatcherService())->dispatch(200),'webhooks'=>static fn()=>(new WebhookService())->dispatch(100),'attendance'=>static function():array{$queued=(new AttendanceNotificationService())->queueDue();$push=(new AttendancePushService())->dispatchPending();return['processed'=>(int)$queued['queued']+(int)$push['delivered'],'failed'=>(int)$push['failed']];}];if(!isset($tasks[$task])){fwrite(STDERR,"Unknown production task.\n");exit(2);}$pdo=db();$lock='officeapp:production:'.$task;$lockStatement=$pdo->prepare('SELECT GET_LOCK(:lock_name,0)');$lockStatement->execute(['lock_name'=>$lock]);if((int)$lockStatement->fetchColumn()!==1){$pdo->prepare("INSERT INTO operations_task_runs(task_name,status,started_at,finished_at,runner_id) VALUES(:task,'skipped',NOW(),NOW(),:runner)")->execute(['task'=>$task,'runner'=>gethostname().':'.getmypid()]);exit(0);}$pdo->prepare("INSERT INTO operations_task_runs(task_name,status,started_at,runner_id) VALUES(:task,'running',NOW(),:runner)")->execute(['task'=>$task,'runner'=>gethostname().':'.getmypid()]);$run=(int)$pdo->lastInsertId();try{$result=$tasks[$task]();$processed=(int)($result['processed']??$result['delivered']??0);$failed=(int)($result['failed']??0);$status=$failed===0?'succeeded':'failed';$pdo->prepare('UPDATE operations_task_runs SET status=:status,finished_at=NOW(),processed_count=:processed,failed_count=:failed WHERE task_run_id=:run')->execute(['status'=>$status,'processed'=>$processed,'failed'=>$failed,'run'=>$run]);exit($failed===0?0:1);}catch(Throwable $e){$pdo->prepare("UPDATE operations_task_runs SET status='failed',finished_at=NOW(),failed_count=1,last_error=:error WHERE task_run_id=:run")->execute(['error'=>mb_substr($e->getMessage(),0,500),'run'=>$run]);exit(1);}finally{$pdo->prepare('SELECT RELEASE_LOCK(:lock_name)')->execute(['lock_name'=>$lock]);}
